'use client'

import LoginForm from '@/components/LoginForm'

export default function LoginPage() {
  return (
    <div style={{
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      minHeight: '100vh',
      background: '#18191A'

/* global process */
import crypto from 'crypto';
import express from 'express';
import cors from 'cors';
import jwt from 'jsonwebtoken';
import mongoose from 'mongoose';
import dotenv from 'dotenv';
import nodemailer from 'nodemailer';
import path from 'path';
import { fileURLToPath } from 'url';
import { User } from './models.js';

import customersRouter from './customers.js';
import carriersRouter from './carriers.js';
import invoicesRouter from './invoices.js';
import exceptionsRouter from './exceptions.js';
import messagesRouter from './messages.js';
import rateLogicRouter from './rateLogic.js';
import dashboardRouter from './dashboard.js';
import reportsRouter from './reports.js';
import uploadsRouter from './uploads.js';
import invoiceImagesRouter from './invoiceImages.js';
import ediRouter from './edi.js';

import vehiclesRouter from './vehicles.js';
import driversRouter from './drivers.js';
import tripsRouter from './trips.js';

dotenv.config();

const app = express();
const PORT = process.env.PORT || 4000;
const JWT_SECRET = process.env.JWT_SECRET || 'dev_secret_change_me';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const distPath = path.resolve(__dirname, '../dist');

const resetTokens = {};
let mongoLastError = '';
const PASSWORD_HASH_SALT = process.env.PASSWORD_HASH_SALT || 'fbpa-default-salt';
const allowVercelOrigins = true;

function hashPassword(password) {
  return crypto
    .createHash('sha256')
    .update(`${PASSWORD_HASH_SALT}:${String(password || '')}`)
    .digest('hex');
}

function buildMongoUri() {
  const explicitUri = (process.env.MONGODB_URI || '').trim();
  if (explicitUri) return explicitUri;

  const user = process.env.MONGODB_USER;
  const password = process.env.MONGODB_PASSWORD;
  const host = process.env.MONGODB_HOST;
  const db = process.env.MONGODB_DB || 'fbpa-db';

  if (!user || !password || !host) return '';

  const encodedUser = encodeURIComponent(String(user));
  const encodedPassword = encodeURIComponent(String(password));
  return `mongodb+srv://${encodedUser}:${encodedPassword}@${host}/${db}?retryWrites=true&w=majority`;
}

const MONGODB_URI = buildMongoUri();
const hasUriPlaceholders = /<[^>]+>/.test(MONGODB_URI);

mongoose.set('strictQuery', true);
mongoose.set('bufferCommands', false);

if (MONGODB_URI && !hasUriPlaceholders) {
  mongoose.connect(MONGODB_URI, {
    serverSelectionTimeoutMS: 10000,
    connectTimeoutMS: 10000,
  })
    .then(() => {
      mongoLastError = '';
      console.log('[mongodb] Connected');
    })
    .catch((err) => {
      mongoLastError = err.message;
      console.error('[mongodb] Connection error:', err.message);
    });

  mongoose.connection.on('disconnected', () => {
    console.warn('[mongodb] Disconnected');
  });

  mongoose.connection.on('error', (err) => {
    mongoLastError = err.message;
    console.error('[mongodb] Error:', err.message);
  });
} else if (hasUriPlaceholders) {
  mongoLastError = 'MONGODB_URI contains placeholder brackets';
  console.warn('[mongodb] MONGODB_URI contains placeholder brackets. Update .env with real credentials.');
} else {
  mongoLastError = 'MONGODB_URI is not set';
  console.warn('[mongodb] MONGODB_URI not set, running without database');
}

const transporter = nodemailer.createTransport({
  host: process.env.SMTP_HOST || 'smtp.ethereal.email',
  port: 587,
  auth: {
    user: process.env.SMTP_USER || '',
    pass: process.env.SMTP_PASS || '',
  },
});

const defaultAllowedOrigins = [
  'http://localhost:5173',
  'http://localhost:5174',
  'http://localhost:5175',
  'http://localhost:5176',
  'http://localhost:5177',
  'http://localhost:5178',
  'http://localhost:5179',
  'https://fbpa-f073sj7mi-josephmabbinante-a11ys-projects.vercel.app',
  'https://fbpa-e3wffttsx-josephmabbinante-a11ys-projects.vercel.app',
  'https://fbpa-ui-git-fbpa-josephmabbinante-a11ys-projects.vercel.app',
  /^https:\/\/.*\.vercel\.app$/,
];

const envAllowedOrigins = (process.env.CORS_ORIGIN || '')
  .split(',')
  .map((origin) => origin.trim())
  .filter(Boolean);

const allowedOrigins = [...new Set([...defaultAllowedOrigins, ...envAllowedOrigins])];
function isOriginAllowed(origin) {
  return allowedOrigins.some((entry) => (entry instanceof RegExp ? entry.test(origin) : entry === origin));
}

app.use(cors({
  origin(origin, callback) {
    if (!origin || isOriginAllowed(origin)) {
      callback(null, true);
      return;
    }

    if (allowVercelOrigins) {
      try {
        const hostname = new URL(origin).hostname;
        if (hostname.endsWith('.vercel.app')) {
          callback(null, true);
          return;
        }
      } catch {
        // Ignore invalid origin format and fall through to denial.
      }
    }

    callback(new Error(`CORS origin not allowed: ${origin}`));
  },
  credentials: true,
}));

app.use(express.json());


app.use('/api/customers', customersRouter);
app.use('/api/carriers', carriersRouter);
app.use('/api/invoices', invoicesRouter);
app.use('/api/exceptions', exceptionsRouter);
app.use('/api/messages', messagesRouter);
app.use('/api/rate-logic', rateLogicRouter);
app.use('/api/dashboard', dashboardRouter);
app.use('/api/reports', reportsRouter);
app.use('/api/uploads', uploadsRouter);
app.use('/api/invoice-images', invoiceImagesRouter);
app.use('/api/edi', ediRouter);

// Fleet data routers
app.use('/api/vehicles', vehiclesRouter);
app.use('/api/drivers', driversRouter);
app.use('/api/trips', tripsRouter);

app.get('/api/health', (req, res) => {
  res.json({ status: 'ok' });
});

const users = [
  { id: 'u-1', email: 'admin@opscale.ai', role: 'admin', password: 'password123' },
];

const handleLogin = (req, res) => {
  const { email, password } = req.body || {};
  const allowAny = process.env.DEV_AUTH_ALLOW_ANY === 'true';
  const user = users.find((u) => u.email === email && u.password === password);
  const authedUser = user || (allowAny && email && password
    ? { id: `u-${Date.now()}`, email, role: 'admin' }
    : null);

  if (!authedUser) return res.status(401).json({ error: 'Invalid credentials' });

  const accessToken = jwt.sign(
    { sub: authedUser.id, email: authedUser.email, role: authedUser.role },
    JWT_SECRET,
    { expiresIn: '1h' }
  );

  return res.json({
    accessToken,
    user: { id: authedUser.id, email: authedUser.email, role: authedUser.role },
  });
};

app.post('/auth/login', handleLogin);
app.post('/api/auth/login', handleLogin);

const handleRegister = (req, res) => {
  const { email, password, role, name } = req.body || {};
  const normalizedEmail = String(email || '').trim().toLowerCase();
  const passwordText = String(password || '');

  if (!normalizedEmail || !passwordText) {
    return res.status(400).json({ error: 'Email and password are required' });
  }
  if (users.some((u) => u.email.toLowerCase() === normalizedEmail)) {
    return res.status(409).json({ error: 'User already exists' });
  }

  const user = {
    id: `u-${Date.now()}`,
    email: normalizedEmail,
    name: String(name || '').trim() || null,
    role: role === 'admin' ? 'admin' : 'user',
    password: passwordText,
  };
  users.push(user);

  return res.status(201).json({
    user: { id: user.id, email: user.email, name: user.name, role: user.role },
  });
};

const handleListUsers = (_req, res) => {
  return res.json({
    users: users.map(({ id, email, name, role }) => ({ id, email, name: name || '', role })),
  });
};

const handleUpdateUser = (req, res) => {
  const userId = String(req.params.id || '').trim();
  const { name, role } = req.body || {};

  if (!userId) {
    return res.status(400).json({ error: 'User id is required' });
  }

  const user = users.find((u) => u.id === userId);
  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  if (typeof name === 'string') {
    user.name = name.trim() || null;
  }

  if (typeof role === 'string') {
    user.role = role === 'admin' ? 'admin' : 'user';
  }

  return res.json({
    user: { id: user.id, email: user.email, name: user.name || '', role: user.role },
  });
};

app.post('/api/auth/register', handleRegister);
app.post('/auth/register', handleRegister);
app.get('/api/auth/users', handleListUsers);
app.get('/auth/users', handleListUsers);
app.patch('/api/auth/users/:id', handleUpdateUser);
app.patch('/auth/users/:id', handleUpdateUser);

app.post('/api/auth/forgot-password', async (req, res) => {
  const { email } = req.body || {};
  if (!email) return res.status(400).json({ error: 'Email required' });

  const token = Math.random().toString(36).slice(2) + Date.now();
  resetTokens[email] = { token, expires: Date.now() + 1000 * 60 * 15 };
  const resetUrl = `${process.env.VITE_API_URL || 'http://localhost:4000'}/reset-password?token=${token}&email=${encodeURIComponent(email)}`;

  try {
    await transporter.sendMail({
      from: process.env.SMTP_FROM || 'noreply@audit-iq.com',
      to: email,
      subject: 'Password Reset',
      text: `Reset your password: ${resetUrl}`,
    });
    return res.json({ success: true });
  } catch (e) {
    return res.status(500).json({ error: e.message });
  }
});

app.post('/auth/forgot-password', async (req, res) => {
  const { email } = req.body || {};
  if (!email) return res.status(400).json({ error: 'Email required' });

  try {
    const normalizedEmail = String(email).trim().toLowerCase();
    const user = await User.findOne({ email: normalizedEmail });
    if (!user) return res.status(404).json({ error: 'User not found' });

    const token = crypto.randomBytes(24).toString('hex');
    resetTokens[token] = { email: normalizedEmail, expires: Date.now() + 3600 * 1000 };
    return res.json({ ok: true, token });
  } catch (err) {
    return res.status(500).json({ error: 'Forgot password failed', details: err.message });
  }
});

app.post('/auth/reset-password', async (req, res) => {
  const { token, password } = req.body || {};
  if (!token || !password) return res.status(400).json({ error: 'Token and password required' });
  if (String(password).length < 8) return res.status(400).json({ error: 'Password must be at least 8 characters' });

  try {
    const entry = resetTokens[token];
    if (!entry || entry.expires < Date.now()) return res.status(400).json({ error: 'Invalid or expired token' });

    const user = await User.findOne({ email: entry.email });
    if (!user) return res.status(404).json({ error: 'User not found' });

    user.password = hashPassword(password);
    await user.save();
    delete resetTokens[token];
    return res.json({ ok: true });
  } catch (err) {
    return res.status(500).json({ error: 'Reset password failed', details: err.message });
  }
});

if (process.env.SERVE_STATIC === 'true') {
  app.use(express.static(distPath));

  app.get('*', (req, res, next) => {
    if (req.path.startsWith('/api') || req.path.startsWith('/auth')) {
      next();
      return;
    }
    res.sendFile(path.join(distPath, 'index.html'));
  });
}

app.listen(PORT, () => {
  console.log(`Auth server running on http://localhost:${PORT}`);
});

// server/messages.js
import express from 'express';
import nodemailer from 'nodemailer';

const router = express.Router();

// In-memory activity log (for demo)
const activityLog = [];

const hasSmtpCredentials = Boolean(process.env.SMTP_USER && process.env.SMTP_PASS);

// Configure nodemailer (for demo, use ethereal.email or your SMTP)
const transporter = nodemailer.createTransport({
  host: process.env.SMTP_HOST || 'smtp.ethereal.email',
  port: 587,
  auth: {
    user: process.env.SMTP_USER || '',
    pass: process.env.SMTP_PASS || '',
  },
});

// Send message and log activity
router.post('/send', async (req, res) => {
  const payload = req.body || {};
  const directTo = payload.to;
  const context = payload.context || {
    customer: payload.customer,
    invoice: payload.invoice,
    exception: payload.exception,
  };

  const to =
    directTo ||
    payload.customer?.email ||
    payload.context?.customer?.email ||
    payload.context?.email;

  const subject =
    payload.subject ||
    `Update for ${payload.invoice?.invoiceNumber || payload.context?.invoice?.invoiceNumber || 'invoice'}`;

  const text = payload.text || payload.message;

  if (!to || !subject || !text) return res.status(400).json({ error: 'Missing fields' });
  try {
    let messageId = `local-${Date.now()}`;
    if (hasSmtpCredentials) {
      const info = await transporter.sendMail({
        from: process.env.SMTP_FROM || 'noreply@audit-iq.com',
        to,
        subject,
        text,
      });
      messageId = info.messageId;
    }

    // Log activity
    activityLog.push({
      to, subject, text, context, date: new Date().toISOString(), messageId,
    });
    res.json({ success: true, messageId, delivery: hasSmtpCredentials ? 'smtp' : 'local-log-only' });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// Get activity log (optionally filter by context)
router.get('/activity', (req, res) => {
  const { customerId, invoiceId, exceptionId } = req.query;
  let filtered = activityLog;
  if (customerId) filtered = filtered.filter(a => a.context?.customerId === customerId);
  if (invoiceId) filtered = filtered.filter(a => a.context?.invoiceId === invoiceId);
  if (exceptionId) filtered = filtered.filter(a => a.context?.exceptionId === exceptionId);
  res.json(filtered);
});

export default router;

import express from 'express';
import multer from 'multer';

import fs from 'fs';
import path from 'path';
const router = express.Router();
const upload = multer({
  dest: path.join(process.cwd(), 'uploads'),
  limits: { fileSize: 10 * 1024 * 1024 }, // 10MB limit
  fileFilter: (req, file, cb) => {
    if (file.mimetype === 'text/csv' || file.mimetype === 'application/vnd.ms-excel' || file.originalname.toLowerCase().endsWith('.csv')) {
      cb(null, true);
    } else {
      cb(new Error('Only CSV files are allowed'));
    }
  },
});

router.post('/', upload.single('file'), async (req, res) => {
  const body = req.body || {};

  if (req.file) {
    // Save file to disk (already in uploads/), parse if CSV
    const filePath = req.file.path;
    let invoiceRows = [];
    let errorRows = [];
    let invoiceCount = 0;
    if (req.file.mimetype === 'text/csv' || req.file.originalname.toLowerCase().endsWith('.csv')) {
      try {
        const csv = fs.readFileSync(filePath, 'utf8');
        const lines = csv.split(/\r?\n/).filter(l => l.trim() !== '');
        const headers = lines[0].split(',').map(h => h.trim());
        for (let i = 1; i < lines.length; i++) {
          const row = lines[i].split(',');
          if (row.length === headers.length) {
            const invoice = {};
            headers.forEach((h, idx) => { invoice[h] = row[idx]; });
            invoiceRows.push(invoice);
          } else {
            errorRows.push({ line: i + 1, value: lines[i] });
          }
        }
        invoiceCount = invoiceRows.length;
      } catch (err) {
        return res.status(400).json({ error: 'Failed to parse CSV', details: err.message });
      }
    }
    return res.status(201).json({
      success: true,
      fileName: req.file.originalname,
      size: req.file.size,
      uploadedAt: new Date().toISOString(),
      invoiceCount,
      successCount: invoiceRows.length,
      errorCount: errorRows.length,
      errors: errorRows,
      invoices: invoiceRows.slice(0, 5), // preview first 5
    });
  }

  const fileName = String(body.fileName || '').trim();
  const invoiceCount = Number(body.invoiceCount || 0);
  if (!fileName) {
    return res.status(400).json({ error: 'fileName is required' });
  }

  return res.status(201).json({
    success: true,
    fileName,
    invoiceCount: Number.isFinite(invoiceCount) ? invoiceCount : 0,
    uploadedAt: new Date().toISOString(),
  });
});

export default router;

import mockInvoices from '../mock/invoices';
import mockExceptions from '../mock/exceptions';
import mockDashboard from '../mock/dashboard';
import mockReports from '../mock/reports';

const RAW_API_URL = import.meta.env.VITE_API_URL;
const API_URL = import.meta.env.PROD
  ? ''
  : (RAW_API_URL ? RAW_API_URL.replace(/\/+$/, '') : '');

function apiUrl(path) {
  return `${API_URL}${path}`;
}

// Send customer message and log activity
export async function sendCustomerMessage({ message, customer, invoice, exception }) {
  try {
    const res = await fetch(apiUrl('/api/messages/send'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ message, customer, invoice, exception }),
    });
    if (!res.ok) throw new Error(`Send failed ${res.status}`);
    return await res.json();
  } catch (err) {
    console.error('sendCustomerMessage error:', err);
    return { error: err.message };
  }
}

function isMockMode() {
  if (import.meta.env.VITE_MOCK_MODE === 'true') return true;
  try {
    return typeof window !== 'undefined' && localStorage.getItem('demoMode') === 'true';
  } catch {
    return false;
  }
}

// Removed JWT token retrieval

async function safeFetch(path, options) {
  try {
    const headers = {
      ...(options && options.headers ? options.headers : {}),
    };
    const res = await fetch(apiUrl(path), { ...options, headers });
    if (!res.ok) throw new Error(`Request failed with ${res.status}`);
    return await res.json();
  } catch (err) {
    console.error("safeFetch error:", path, err);
    return { error: err.message };
  }
}


export async function getInvoices(type) {
  if (isMockMode()) {
    return mockInvoices;
  }
  const query = type ? `?type=${encodeURIComponent(type)}` : '';
  return safeFetch(`/api/invoices${query}`);
}

export async function getCustomers() {
  if (isMockMode()) {
    return [];
  }
  return safeFetch('/api/customers');
}

export async function getCustomerDetail(id) {
  if (!id) return { error: 'Customer id is required' };
  return safeFetch(`/api/customers/${encodeURIComponent(id)}`);
}

export async function getCustomerAging(id) {
  if (!id) return { error: 'Customer id is required' };
  return safeFetch(`/api/customers/${encodeURIComponent(id)}/aging`);
}

export async function getCarriers() {
  if (isMockMode()) {
    return [];
  }
  return safeFetch('/api/carriers');
}

export async function createInvoice(payload) {
  try {
    const token = getAccessToken();
    const res = await fetch(apiUrl('/api/invoices'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
      body: JSON.stringify(payload),
    });
    if (!res.ok) throw new Error(`Create invoice failed ${res.status}`);
    return await res.json();
  } catch (err) {
    console.error('createInvoice error:', err);
    return { error: err.message };
  }
}

export async function getExceptions() {
  if (isMockMode()) {
    return mockExceptions;
  }
  return safeFetch('/api/exceptions');
}

export async function getDashboard() {
  if (isMockMode()) {
    return mockDashboard;
  }
  return safeFetch('/api/dashboard');
}

export async function getReports() {
  if (isMockMode()) {
    return mockReports;
  }
  return safeFetch('/api/reports');
}

export async function login(payload) {
  console.log('Frontend login payload:', payload);
  try {
    const res = await fetch(apiUrl('/api/auth/login'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    if (!res.ok) {
      const errorData = await res.json().catch(() => null);
      throw new Error(errorData?.error || `Login failed ${res.status}`);
    }
    return await res.json();
  } catch (err) {
    console.error('login error:', err);
    return { error: err.message };
  }
}

export async function connectEdiIntegration(payload) {
  try {
    const res = await fetch(apiUrl('/api/edi/connect'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    if (!res.ok) throw new Error(`Connect failed ${res.status}`);
    return await res.json();
  } catch (err) {
    console.error('connectEdiIntegration error:', err);
    return { error: err.message };
  }
}

export function getInvoiceImages(invoiceId) {
  const query = invoiceId ? `?invoiceId=${encodeURIComponent(invoiceId)}` : '';
  return safeFetch(`/api/invoice-images${query}`);
}

export async function uploadInvoiceImage(payload) {
  try {
    const fd = new FormData();
    fd.append('file', payload.file);
    fd.append('invoiceId', payload.invoiceId);
    if (payload.notes) fd.append('notes', payload.notes);

    const res = await fetch(apiUrl('/api/invoice-images'), {
      method: 'POST',
      body: fd,
    });
    if (!res.ok) throw new Error(`Upload failed ${res.status}`);
    return await res.json();
  } catch (err) {
    console.error('uploadInvoiceImage error:', err);
    return { error: err.message };
  }
}

export async function verifyInvoiceImage(payload) {
  try {
    const res = await fetch(apiUrl('/api/invoice-images/verify'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        imageId: payload.imageId,
        invoiceId: payload.invoiceId,
      }),
    });
    if (!res.ok) throw new Error(`Verify failed ${res.status}`);
    return await res.json();
  } catch (err) {
    console.error('verifyInvoiceImage error:', err);
    return { error: err.message };
  }
}

export async function uploadInvoiceFile(payload) {
  // payload can be a File object (legacy) or an object { fileName, invoiceCount }
  try {
    let body;
    let headers = {};

    if (payload instanceof File) {
      // legacy: send as FormData
      const fd = new FormData();
      fd.append('file', payload);
      body = fd;
    } else if (payload && typeof payload === 'object') {
      body = JSON.stringify({ fileName: payload.fileName, invoiceCount: payload.invoiceCount });
      headers['Content-Type'] = 'application/json';
    } else {
      return { error: 'Invalid upload payload' };
    }

    const res = await fetch(apiUrl('/api/uploads'), {
      method: 'POST',
      headers: { ...headers },
      body
    });

    if (!res.ok) throw new Error(`Upload failed ${res.status}`);
    return await res.json();
  } catch (err) {
    console.error('uploadInvoiceFile error:', err);
    return { error: err.message };
  }
}

export async function calculateRateLogic(payload) {
  return safeFetch('/api/rate-logic/calculate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
}

export async function register(payload) {
  console.log('Frontend register payload:', payload);
  try {
    const res = await fetch(apiUrl('/api/auth/register'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    if (!res.ok) {
