import { useMemo, useState } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { useTheme, themes } from '../contexts/ThemeContext';

/**
 * Horizontal bar chart showing savings by carrier
 * Replaces the Top Carriers table with visual representation
 * Clickable for navigation
 */
export default function SavingsByCarrierChart({ data, onClick }) {
  const { theme } = useTheme();
  const t = themes[theme];
  const [isHovered, setIsHovered] = useState(false);

  const [lastValidData, setLastValidData] = useState([]);
  const chartData = useMemo(() => {
    const arr = (data || [])
      .map((item, index) => {
        const rawSavings = Number(item?.savings ?? item?.total ?? item?.value ?? 0);
        const rawCount = Number(item?.invoiceCount ?? item?.count ?? 0);
        return {
          carrier: item?.carrier || item?.lane || `Item ${index + 1}`,
          savings: Number.isFinite(rawSavings) ? rawSavings : 0,
          invoiceCount: Number.isFinite(rawCount) ? rawCount : 0,
        };
      })
      .filter((item) => item.savings > 0);
    if (arr.length) setLastValidData(arr);
    return arr;
  }, [data]);
  const chartDataToUse = chartData.length ? chartData : lastValidData;

  return (
    <div
      onClick={onClick}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      style={{
        width: '100%',
        height: 360,
        backgroundColor: isHovered ? t.bgAlt : t.surface,
        border: `1px solid ${isHovered ? t.accent : t.border}`,
        borderRadius: '4px',
        padding: '16px',
        display: 'flex',
        flexDirection: 'column',
        boxSizing: 'border-box',
        cursor: onClick ? 'pointer' : 'default',
        transition: 'background-color 0.2s ease, border-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease',
        transform: onClick && isHovered ? 'translateY(-2px)' : 'translateY(0)',
        boxShadow: onClick && isHovered ? `0 4px 12px ${t.accent}20` : 'none',
      }}
    >
      <h3
        style={{
          fontSize: '13px',
          fontWeight: '600',
          margin: '0 0 12px 0',
          color: t.text,
          textTransform: 'uppercase',
          letterSpacing: '0.3px',
        }}
      >
        Savings by Carrier
        {onClick && <span style={{ fontSize: '11px', marginLeft: '8px', opacity: 0.6 }}>- Click for details</span>}
      </h3>

      <div style={{ flex: 1, minHeight: 0, width: '100%' }}>
        {chartData.length ? (
          <ResponsiveContainer width="100%" height="100%" debounce={60}>
            <BarChart
              data={chartData}
              layout="vertical"
              margin={{ top: 5, right: 30, left: 100 }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke={t.borderLight} />
              <XAxis
                type="number"
                tick={{ fill: t.textSecondary, fontSize: 11 }}
                tickFormatter={(value) => `$${(Number(value) / 1000).toFixed(1)}k`}
              />
              <YAxis
                dataKey="carrier"
                type="category"
                tick={{ fill: t.textSecondary, fontSize: 11 }}
                width={95}
              />
              <Bar
                dataKey="savings"
                fill={t.accent}
                radius={[4, 4, 0, 0]}
                minPointSize={2}
                maxBarSize={32}
              >
                {/* Add <Cell> elements here if needed */}
              </Bar>
              <Tooltip
                contentStyle={{
                  backgroundColor: t.bgAlt,
                  border: `1px solid ${t.border}`,
                  borderRadius: '4px',
                  color: t.text,
                  fontSize: '12px',
                }}
              />
            </BarChart>
          </ResponsiveContainer>
        ) : (
          <div style={{ height: '100%', display: 'grid', placeItems: 'center', border: `1px dashed ${t.border}`, borderRadius: 4, color: t.textSecondary, fontSize: 12 }}>
            No carrier savings data available
          </div>
        )}
      </div>

      {/* Summary stats below chart */}
      <div
        style={{
          marginTop: 12,
          paddingTop: 12,
          borderTop: `1px solid ${t.borderLight}`,
          fontSize: '12px',
          color: t.textSecondary,
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))',
          gap: 12,
        }}
      >
        {chartData.map((item) => (
          <div key={item.carrier}>
            <div style={{ color: t.text, fontWeight: '600' }}>{item.carrier}</div>
            <div>{item.invoiceCount} invoices</div>
          </div>
        ))}
      </div>
    </div>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { NavLink, useNavigate } from 'react-router-dom';
import { useTheme, themes } from '../contexts/ThemeContext';
import logo from '../assets/opscale-logo.svg';
import { clearAccessToken } from '../utils/authToken';

const navItems = [
  { id: 'dashboard', label: 'Dashboard', icon: 'DB', path: '/' },
  { id: 'fleet-dashboard', label: 'Fleet Dashboard', icon: 'FD', path: '/fleet' },
  // Orders and Order Management removed
  // Customers and Carriers removed
  { id: 'invoices', label: 'Invoices', icon: 'IN', path: '/invoices' },
  { id: 'exceptions', label: 'Exceptions', icon: 'EX', path: '/exceptions' },
  { id: 'rate-logic', label: 'Rate Logic Tool', icon: 'RL', path: '/rate-logic' },
  { id: 'reports', label: 'Reports', icon: 'RP', path: '/reports' },
  { id: 'uploads', label: 'Uploads', icon: 'UP', path: '/uploads' },
  { id: 'settings', label: 'Settings', icon: 'ST', path: '/settings' },
];

export default function Sidebar() {
  const { theme, toggleTheme } = useTheme();
  const t = themes[theme];
  const navigate = useNavigate();
  const [collapsed, setCollapsed] = useState(false);
  const [isMobile, setIsMobile] = useState(false);
  const [showMobileSidebar, setShowMobileSidebar] = useState(false);

  // Responsive: detect mobile
  useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth < 900);
    };
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  // Dropdown state for groups
  const [openDropdowns, setOpenDropdowns] = useState({});
  const handleDropdownToggle = (groupId) => {
    setOpenDropdowns((prev) => ({ ...prev, [groupId]: !prev[groupId] }));
  };

  // Sidebar width (example, adjust as needed)
  const sidebarWidth = collapsed ? 60 : 240;
  const navGap = collapsed ? 4 : 10;

  // Show sidebar on mobile only when showMobileSidebar is true
  // On desktop, always show (collapsed or not)
  const sidebarVisible = isMobile ? showMobileSidebar : true;

  return (
    <>
      {/* Overlay for mobile menu */}
      {isMobile && showMobileSidebar && (
        <div
          onClick={() => setShowMobileSidebar(false)}
          style={{
            position: 'fixed',
            inset: 0,
            background: 'rgba(0,0,0,0.45)',
            zIndex: 99,
            transition: 'opacity 0.2s',
          }}
        />
      )}
      <aside
        style={{
          width: sidebarWidth,
          display: sidebarVisible ? 'flex' : 'none',
          flexDirection: 'column',
          position: 'fixed',
          inset: '0 auto 0 0',
          background: `linear-gradient(185deg, ${t.bgAlt}, ${t.surface})`,
          borderRight: `1px solid ${t.border}`,
          boxShadow: '18px 0 36px rgba(1, 5, 18, 0.45)',
          zIndex: 100,
          transition: 'width 200ms ease',
        }}
      >
      <header
        style={{
          minHeight: 70,
          display: 'flex',
          alignItems: 'center',
          justifyContent: collapsed ? 'center' : 'space-between',
          padding: collapsed ? '12px 8px' : '12px 14px',
          borderBottom: `1px solid ${t.border}`,
          gap: 8,
        }}
      >
        {!collapsed && <img src={logo} alt="Opscale Audit IQ" style={{ height: 40, width: 'auto' }} />}
        <button
          type="button"
          onClick={() => {
            if (isMobile) {
              setShowMobileSidebar((v) => !v);
            } else {
              setCollapsed((c) => !c);
            }
          }}
          className="neon-outline"
          style={{
            width: 32,
            height: 32,
            borderRadius: 10,
            border: `1px solid ${t.border}`,
            backgroundColor: t.surfaceStrong,
            color: t.textSecondary,
            cursor: 'pointer',
          }}
          title={collapsed ? 'Expand Sidebar' : 'Collapse Sidebar'}
        >
          {isMobile ? (showMobileSidebar ? '×' : '≡') : collapsed ? '>' : '<'}
        </button>
      </header>

      <nav
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: navGap,
          padding: '14px 10px',
          overflowY: 'auto',
          flex: 1,
        }}
      >
        {navItems.map((item) =>
          item.dropdown ? (
            <div key={item.id} style={{ marginBottom: 4 }}>
              <button
                type="button"
                onClick={() => handleDropdownToggle(item.id)}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 10,
                  borderRadius: 12,
                  border: `1px solid ${openDropdowns[item.id] ? t.accent : t.border}`,
                  background: openDropdowns[item.id]
                    ? `linear-gradient(140deg, rgba(24, 210, 255, 0.12), rgba(95, 140, 255, 0.10))`
                    : 'transparent',
                  color: openDropdowns[item.id] ? t.text : t.textSecondary,
                  padding: collapsed ? '10px 8px' : '10px 12px',
                  fontSize: 13,
                  fontWeight: 600,
                  width: '100%',
                  cursor: 'pointer',
                  transition: 'all 180ms ease',
                }}
                aria-expanded={openDropdowns[item.id]}
                aria-controls={`dropdown-${item.id}`}
              >
                <span
                  style={{
                    minWidth: 34,
                    height: 30,
                    display: 'inline-flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    borderRadius: 8,
                    backgroundColor: 'rgba(255,255,255,0.05)',
                    border: `1px solid ${t.border}`,
                    fontSize: 11,
                    letterSpacing: 0.4,
                  }}
                >
                  {item.icon}
                </span>
                {!collapsed && <span style={{ whiteSpace: 'nowrap' }}>{item.label}</span>}
                {!collapsed && <span style={{ marginLeft: 'auto', fontSize: 16 }}>{openDropdowns[item.id] ? '▾' : '▸'}</span>}
              </button>
              {openDropdowns[item.id] && (
                <div id={`dropdown-${item.id}`} style={{ marginLeft: collapsed ? 0 : 36, marginTop: 2 }}>
                  {item.items.map((sub) => (
                    <NavLink
                      key={sub.id}
                      to={sub.path}
                      className="neon-outline"
                      style={({ isActive }) => ({
                        display: 'flex',
                        alignItems: 'center',
                        gap: 10,
                        borderRadius: 10,
                        border: `1px solid ${isActive ? t.accent : t.border}`,
                        background: isActive
                          ? `linear-gradient(140deg, rgba(24, 210, 255, 0.18), rgba(95, 140, 255, 0.14))`
                          : 'transparent',
                        color: isActive ? t.text : t.textSecondary,
                        padding: collapsed ? '8px 8px' : '8px 12px',
                        fontSize: 12,
                        fontWeight: 500,
                        marginBottom: 2,
                        transition: 'all 180ms ease',
                      })}
                    >
                      <span
                        style={{
                          minWidth: 24,
                          height: 22,
                          display: 'inline-flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          borderRadius: 6,
                          backgroundColor: 'rgba(255,255,255,0.04)',
                          border: `1px solid ${t.border}`,
                          fontSize: 10,
                          letterSpacing: 0.3,
                        }}
                      >
                        {sub.icon}
                      </span>
                      {!collapsed && <span style={{ whiteSpace: 'nowrap' }}>{sub.label}</span>}
                    </NavLink>
                  ))}
                </div>
              )}
            </div>
          ) : (
            <NavLink
              key={item.id}
              to={item.path}
              className="neon-outline"
              end={item.path === '/'}
              style={({ isActive }) => ({
                display: 'flex',
                alignItems: 'center',
                gap: 10,
                borderRadius: 12,
                border: `1px solid ${isActive ? t.accent : t.border}`,
                background: isActive
                  ? `linear-gradient(140deg, rgba(24, 210, 255, 0.22), rgba(95, 140, 255, 0.18))`
                  : 'transparent',
                color: isActive ? t.text : t.textSecondary,
                padding: collapsed ? '10px 8px' : '10px 12px',
                fontSize: 13,
                fontWeight: 600,
                transition: 'all 180ms ease',
                boxShadow: isActive ? 'inset 0 0 0 1px rgba(255,255,255,0.04)' : 'none',
              })}
            >
              <span
                style={{
                  minWidth: 34,
                  height: 30,
                  display: 'inline-flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  borderRadius: 8,
                  backgroundColor: 'rgba(255,255,255,0.05)',
                  border: `1px solid ${t.border}`,
                  fontSize: 11,
                  letterSpacing: 0.4,
                }}
              >
                {item.icon}
              </span>
              {!collapsed && <span style={{ whiteSpace: 'nowrap' }}>{item.label}</span>}
            </NavLink>
          )
        )}
      </nav>

      <footer style={{ padding: 10, borderTop: `1px solid ${t.border}` }}>
        <button
          type="button"
          className="neon-outline"
          onClick={() => {
            clearAccessToken();
            navigate('/login');
          }}
          style={{
            width: '100%',
            minHeight: 42,
            borderRadius: 12,
            border: `1px solid ${t.border}`,
            background: `linear-gradient(145deg, ${t.surfaceStrong}, ${t.surface})`,
            color: t.textSecondary,
            cursor: 'pointer',
            fontSize: 13,
            fontWeight: 600,
          }}
        >
          Log Out
        </button>
      </footer>
      </aside>
    </>
  );
}

