import { useEffect, useMemo } from 'react';
import {
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  LineChart,
  Line,
} from 'recharts';
import { useTheme, themes } from '../contexts/ThemeContext';
import { useDemo } from '../demo/DemoContext';
import { getCarriers } from '../api/client';
import { Link } from 'react-router-dom';
import carrierPerformance from '../mock/carriersPerformance';
import { useState } from 'react';

function mapCarrierMetrics(carrier, index) {
  const invoiceCount = Number(carrier?.invoiceCount ?? carrier?.totalInvoices ?? 0);
  const totalSpend = Number(carrier?.totalSpend ?? 0);
  const openAP = Number(carrier?.openAP ?? 0);
  const baseline = 88 + ((index % 7) * 1.4);
  return {
    carrier: carrier?.name || carrier?.carrier || `Carrier ${index + 1}`,
    onTime: Number(carrier?.onTime ?? Math.min(99, baseline)),
    billingErrors: Number(carrier?.billingErrors ?? Math.max(0.2, openAP > 0 ? (openAP / Math.max(totalSpend, 1)) * 10 : 1.2)),
    invoiceDiscrepancy: Number(carrier?.invoiceDiscrepancy ?? Math.max(0.1, invoiceCount > 0 ? 100 / (invoiceCount * 5) : 1.0)),
    avgTransitDays: Number(carrier?.avgTransitDays ?? (2.0 + (index % 5) * 0.3)),
    claimsRate: Number(carrier?.claimsRate ?? Math.max(0.1, 2.5 - ((index % 6) * 0.25))),
    totalInvoices: invoiceCount,
  };
}

export default function CarriersPerformance() {
  const { demoMode } = useDemo();
  const [showAddModal, setShowAddModal] = useState(false);
  const [showImportModal, setShowImportModal] = useState(false);
  const [carrierForm, setCarrierForm] = useState({ carrier: '', onTime: '', billingErrors: '', invoiceDiscrepancy: '', avgTransitDays: '', claimsRate: '', totalInvoices: '' });
  const [formError, setFormError] = useState('');
  const [importStatus, setImportStatus] = useState('');
  const [liveCarriers, setLiveCarriers] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const { theme } = useTheme();
  const t = themes[theme];

  useEffect(() => {
    let mounted = true;

    if (demoMode) {
      setLiveCarriers([]);
      setError(null);
      setLoading(false);
      return () => {
        mounted = false;
      };
    }

    setLoading(true);
    getCarriers()
      .then((res) => {
        if (!mounted) return;
        if (res?.error) {
          setError(res.error);
          setLiveCarriers([]);
        } else {
          setLiveCarriers(Array.isArray(res?.carriers) ? res.carriers : []);
          setError(null);
        }
      })
      .catch((err) => {
        if (!mounted) return;
        setError(err.message || String(err));
        setLiveCarriers([]);
      })
      .finally(() => {
        if (mounted) setLoading(false);
      });

    return () => {
      mounted = false;
    };
  }, [demoMode]);

  const data = useMemo(
    () => (demoMode ? carrierPerformance : liveCarriers.map((carrier, index) => mapCarrierMetrics(carrier, index))),
    [demoMode, liveCarriers],
  );

  const summary = useMemo(() => {
    const total = data.length;
    if (!total) return null;
    const avg = (key) => data.reduce((sum, item) => sum + item[key], 0) / total;
    return {
      onTime: avg('onTime'),
      billingErrors: avg('billingErrors'),
      invoiceDiscrepancy: avg('invoiceDiscrepancy'),
      avgTransitDays: avg('avgTransitDays'),
      claimsRate: avg('claimsRate'),
    };
  }, [data]);

  const containerStyle = {
    padding: '24px',
    backgroundColor: t.bg,
    color: t.text,
    minHeight: '100vh',
    width: '100%',
    boxSizing: 'border-box',
  };

  const cardStyle = {
    backgroundColor: t.surface,
    border: `1px solid ${t.border}`,
    borderRadius: 6,
    padding: 16,
  };

  const kpiStyle = {
    backgroundColor: t.bgAlt,
    border: `1px solid ${t.borderLight}`,
    borderRadius: 6,
    padding: 12,
  };

  const tableStyle = {
    width: '100%',
    borderCollapse: 'collapse',
    fontSize: 13,
  };

  const thStyle = {
    padding: '8px 12px',
    textAlign: 'left',
    fontWeight: 600,
    backgroundColor: t.surface,
    borderBottom: `1px solid ${t.border}`,
    color: t.textSecondary,
    fontSize: 11,
    textTransform: 'uppercase',
    letterSpacing: '0.3px',
  };

  const tdStyle = {
    padding: '8px 12px',
    borderBottom: `1px solid ${t.borderLight}`,
    color: t.text,
    fontSize: 12,
  };

  return (
    <div style={containerStyle}>
      {!demoMode && error ? <div style={{ marginBottom: 12, fontSize: 12, color: t.warning }}>{error}</div> : null}
      {!demoMode && loading ? <div style={{ marginBottom: 12, fontSize: 12, color: t.textSecondary }}>Loading carrier metrics...</div> : null}
      <div style={{ display: 'flex', gap: 12, marginBottom: 20 }}>
        <button
          style={{ background: '#1976d2', color: '#fff', border: 'none', borderRadius: 4, padding: '8px 16px', fontWeight: 600, fontSize: 15, cursor: 'pointer' }}
          onClick={() => setShowAddModal(true)}
        >
          + Add Carrier
        </button>
        <button
          style={{ background: '#388e3c', color: '#fff', border: 'none', borderRadius: 4, padding: '8px 16px', fontWeight: 600, fontSize: 15, cursor: 'pointer' }}
          onClick={() => setShowImportModal(true)}
        >
          Import Carrier List (CSV)
        </button>
        <button
          style={{ background: '#6c63ff', color: '#fff', border: 'none', borderRadius: 4, padding: '8px 16px', fontWeight: 600, fontSize: 15, cursor: 'pointer' }}
          title="Integrate with MyCarrierPackets, RTS, etc. (coming soon)"
          disabled
        >
          Integrate with External Platform
        </button>
      </div>

      {/* Add Carrier Modal */}
      {showAddModal && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100vw', height: '100vh', background: 'rgba(0,0,0,0.3)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ background: t.surface, color: t.text, padding: 32, borderRadius: 8, minWidth: 340, boxShadow: '0 2px 16px rgba(0,0,0,0.15)' }}>
            <h2 style={{ fontSize: 18, fontWeight: 700, marginBottom: 16 }}>Add Carrier</h2>
            <form onSubmit={e => {
              e.preventDefault();
              setFormError('');
              if (!carrierForm.carrier) return setFormError('Carrier name is required');
              // Here you would add logic to update the carrier list (API or state)
              setShowAddModal(false);
            }} style={{ display: 'grid', gap: 12 }}>
              <input autoFocus placeholder="Carrier Name*" value={carrierForm.carrier} onChange={e => setCarrierForm(f => ({ ...f, carrier: e.target.value }))} style={{ padding: 8, borderRadius: 4, border: `1px solid ${t.border}` }} />
              <input placeholder="On-Time %" value={carrierForm.onTime} onChange={e => setCarrierForm(f => ({ ...f, onTime: e.target.value }))} style={{ padding: 8, borderRadius: 4, border: `1px solid ${t.border}` }} />
              <input placeholder="Billing Errors %" value={carrierForm.billingErrors} onChange={e => setCarrierForm(f => ({ ...f, billingErrors: e.target.value }))} style={{ padding: 8, borderRadius: 4, border: `1px solid ${t.border}` }} />
              <input placeholder="Invoice Discrepancy %" value={carrierForm.invoiceDiscrepancy} onChange={e => setCarrierForm(f => ({ ...f, invoiceDiscrepancy: e.target.value }))} style={{ padding: 8, borderRadius: 4, border: `1px solid ${t.border}` }} />
              <input placeholder="Avg Transit Days" value={carrierForm.avgTransitDays} onChange={e => setCarrierForm(f => ({ ...f, avgTransitDays: e.target.value }))} style={{ padding: 8, borderRadius: 4, border: `1px solid ${t.border}` }} />
              <input placeholder="Claims Rate %" value={carrierForm.claimsRate} onChange={e => setCarrierForm(f => ({ ...f, claimsRate: e.target.value }))} style={{ padding: 8, borderRadius: 4, border: `1px solid ${t.border}` }} />
              <input placeholder="Total Invoices" value={carrierForm.totalInvoices} onChange={e => setCarrierForm(f => ({ ...f, totalInvoices: e.target.value }))} style={{ padding: 8, borderRadius: 4, border: `1px solid ${t.border}` }} />
              {formError && <div style={{ color: t.error, fontSize: 13 }}>{formError}</div>}
              <div style={{ display: 'flex', gap: 8, marginTop: 8 }}>
                <button type="submit" style={{ background: t.accent, color: '#fff', border: 'none', borderRadius: 4, padding: '8px 16px', fontWeight: 600, cursor: 'pointer' }}>Add</button>
                <button type="button" style={{ background: t.bgAlt, color: t.text, border: `1px solid ${t.border}`, borderRadius: 4, padding: '8px 16px', fontWeight: 500, cursor: 'pointer' }} onClick={() => setShowAddModal(false)}>Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Import Carrier List Modal */}
      {showImportModal && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100vw', height: '100vh', background: 'rgba(0,0,0,0.3)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ background: t.surface, color: t.text, padding: 32, borderRadius: 8, minWidth: 340, boxShadow: '0 2px 16px rgba(0,0,0,0.15)' }}>
            <h2 style={{ fontSize: 18, fontWeight: 700, marginBottom: 16 }}>Import Carrier List (CSV)</h2>
            <form onSubmit={async e => {
              e.preventDefault();
              setImportStatus('');
              const file = e.target.elements.csvfile.files[0];
              if (!file) return setImportStatus('Please select a CSV file.');
              // Here you would add logic to parse and import the CSV
              setImportStatus('Import successful! (mock)');
              setShowImportModal(false);
            }} style={{ display: 'grid', gap: 12 }}>
              <input type="file" name="csvfile" accept=".csv" style={{ marginBottom: 4 }} />
              {importStatus && <div style={{ color: importStatus.includes('success') ? t.positive : t.error, fontSize: 13 }}>{importStatus}</div>}
              <div style={{ display: 'flex', gap: 8, marginTop: 8 }}>
                <button type="submit" style={{ background: t.accent, color: '#fff', border: 'none', borderRadius: 4, padding: '8px 16px', fontWeight: 600, cursor: 'pointer' }}>Import</button>
                <button type="button" style={{ background: t.bgAlt, color: t.text, border: `1px solid ${t.border}`, borderRadius: 4, padding: '8px 16px', fontWeight: 500, cursor: 'pointer' }} onClick={() => setShowImportModal(false)}>Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}
      <div style={{ marginBottom: 20 }}>
        <h1 style={{ fontSize: 24, fontWeight: 700, marginBottom: 6 }}>Carrier Performance</h1>
        <div style={{ fontSize: 12, color: t.textSecondary }}>
          On-time performance, billing errors, and invoice discrepancy metrics by carrier.
        </div>
      </div>

      {summary && (
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))',
            gap: 12,
            marginBottom: 20,
          }}
        >
          <div style={kpiStyle}>
            <div style={{ fontSize: 11, color: t.textSecondary }}>Avg On-Time</div>
            <div style={{ fontSize: 18, fontWeight: 700 }}>{summary.onTime.toFixed(1)}%</div>
          </div>
          <div style={kpiStyle}>
            <div style={{ fontSize: 11, color: t.textSecondary }}>Billing Errors</div>
            <div style={{ fontSize: 18, fontWeight: 700 }}>{summary.billingErrors.toFixed(1)}%</div>
          </div>
          <div style={kpiStyle}>
            <div style={{ fontSize: 11, color: t.textSecondary }}>Invoice Discrepancy</div>
            <div style={{ fontSize: 18, fontWeight: 700 }}>{summary.invoiceDiscrepancy.toFixed(1)}%</div>
          </div>
          <div style={kpiStyle}>
            <div style={{ fontSize: 11, color: t.textSecondary }}>Avg Transit</div>
            <div style={{ fontSize: 18, fontWeight: 700 }}>{summary.avgTransitDays.toFixed(1)} days</div>
          </div>
          <div style={kpiStyle}>
            <div style={{ fontSize: 11, color: t.textSecondary }}>Claims Rate</div>
            <div style={{ fontSize: 18, fontWeight: 700 }}>{summary.claimsRate.toFixed(1)}%</div>
          </div>
        </div>
      )}

      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))',
          gap: 16,
          marginBottom: 20,
        }}
      >
        <div style={cardStyle}>
          <div style={{ fontSize: 12, fontWeight: 600, marginBottom: 8, color: t.textSecondary, textTransform: 'uppercase' }}>
            On-Time Performance
          </div>
          <div style={{ height: 260 }}>
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={data} margin={{ top: 8, right: 16, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke={t.borderLight} />
                <XAxis dataKey="carrier" stroke={t.textSecondary} fontSize={10} />
                <YAxis stroke={t.textSecondary} fontSize={11} />
                <Tooltip
                  contentStyle={{
                    backgroundColor: t.bgAlt,
                    border: `1px solid ${t.border}`,
                    borderRadius: 4,
                    color: t.text,
                    fontSize: 12,
                  }}
                  formatter={(value) => `${value}%`}
                />
                <Bar dataKey="onTime" fill={t.positive} radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div style={cardStyle}>
          <div style={{ fontSize: 12, fontWeight: 600, marginBottom: 8, color: t.textSecondary, textTransform: 'uppercase' }}>
            Billing & Invoice Discrepancies
          </div>
          <div style={{ height: 260 }}>
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={data} margin={{ top: 8, right: 16, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke={t.borderLight} />
                <XAxis dataKey="carrier" stroke={t.textSecondary} fontSize={10} />
                <YAxis stroke={t.textSecondary} fontSize={11} />
                <Tooltip
                  contentStyle={{
                    backgroundColor: t.bgAlt,
                    border: `1px solid ${t.border}`,
                    borderRadius: 4,
                    color: t.text,
                    fontSize: 12,
                  }}
                  formatter={(value) => `${value}%`}
                />
                <Line type="monotone" dataKey="billingErrors" stroke={t.warning} strokeWidth={2} dot={{ r: 3 }} />
                <Line type="monotone" dataKey="invoiceDiscrepancy" stroke={t.error} strokeWidth={2} dot={{ r: 3 }} />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      <div style={{ ...cardStyle, padding: 0, overflowX: 'auto' }}>
        <table style={tableStyle}>
          <thead>
            <tr>
              <th style={thStyle}>Carrier</th>
              <th style={thStyle}>On-Time %</th>
              <th style={thStyle}>Billing Errors %</th>
              <th style={thStyle}>Invoice Discrepancy %</th>
              <th style={thStyle}>Avg Transit (Days)</th>
              <th style={thStyle}>Claims %</th>
              <th style={thStyle}>Invoices</th>
            </tr>
          </thead>
          <tbody>
            {data.map((row) => (
              <tr key={row.carrier}>
                <td style={tdStyle}>
                  <Link
                    to={`/carriers/${encodeURIComponent(row.carrier)}`}
                    style={{ color: '#1976d2', textDecoration: 'underline', cursor: 'pointer', fontWeight: 600 }}
                  >
                    {row.carrier}
                  </Link>
                </td>
                <td style={tdStyle}>{row.onTime.toFixed(1)}%</td>
                <td style={tdStyle}>{row.billingErrors.toFixed(1)}%</td>
                <td style={tdStyle}>{row.invoiceDiscrepancy.toFixed(1)}%</td>
                <td style={tdStyle}>{row.avgTransitDays.toFixed(1)}</td>
                <td style={tdStyle}>{row.claimsRate.toFixed(1)}%</td>
                <td style={tdStyle}>{row.totalInvoices.toLocaleString()}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

// src/pages/Customers.jsx
import { useEffect, useState } from 'react';
import ContactCustomerModal from '../components/ContactCustomerModal';
import { getCustomerAging, getCustomerDetail, getCustomers, sendCustomerMessage } from '../api/client';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { useTheme, themes } from '../contexts/ThemeContext';
import { Link } from 'react-router-dom';

export default function Customers() {
  const { theme } = useTheme();
  const t = themes[theme];
  const [customers, setCustomers] = useState([]);
  const [selected, setSelected] = useState(null);
  const [detail, setDetail] = useState(null);
  const [aging, setAging] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    getCustomers().then((data) => {
      if (Array.isArray(data)) setCustomers(data);
      else setCustomers([]);
    });
  }, []);

  useEffect(() => {
    if (!selected) return setDetail(null);
    setLoading(true);
    Promise.all([
      getCustomerDetail(selected),
      getCustomerAging(selected),
    ]).then(([d, a]) => {
      setDetail(d);
      setAging(a);
      setLoading(false);
    });
  }, [selected]);

  // Contact modal state
  const [modalOpen, setModalOpen] = useState(false);

  const handleSendMessage = async ({ message, customer, invoice, exception }) => {
    return await sendCustomerMessage({ message, customer, invoice, exception });
  };

  return (
    <div style={{ padding: 32, background: t.bg, color: t.text, minHeight: '100vh' }}>
      <h1 style={{ fontSize: 24, fontWeight: 700, marginBottom: 24 }}>Customers</h1>
      <div style={{ display: 'flex', gap: 32 }}>
        <div style={{ minWidth: 260 }}>
          <h2 style={{ fontSize: 16, fontWeight: 600, marginBottom: 12 }}>Customer List</h2>
          <div style={{ fontSize: 12, color: t.textSecondary, marginBottom: 16 }}>
            Customers are created automatically from AR invoices. Use this view to manage profiles and analytics.
          </div>
          <ul id="customer-list" style={{ listStyle: 'none', padding: 0 }}>
            {customers.map((c) => (
              <li key={c.id}>
                <button
                  style={{
                    background: selected === c.id ? t.accent : t.surface,
                    color: selected === c.id ? '#fff' : t.text,
                    border: `1px solid ${t.border}`,
                    borderRadius: 4,
                    padding: '8px 12px',
                    marginBottom: 8,
                    width: '100%',
                    textAlign: 'left',
                    cursor: 'pointer',
                  }}
                  onClick={() => setSelected(c.id)}
                >
                  {c.name}
                </button>
              </li>
            ))}
          </ul>
        </div>
        <div style={{ flex: 1 }} id="customer-analysis">
          {!selected && <div style={{ color: t.textSecondary }}>Select a customer to view details.</div>}
          {loading && <div>Loading...</div>}
          {detail && (
            <div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
                <div>
                  <h2 style={{ fontSize: 20, fontWeight: 700 }}>{detail.name}</h2>
                  <div style={{ marginBottom: 12, color: t.textSecondary }}>
                    {detail.contact} | {detail.email} | {detail.phone}
                  </div>
                  <div style={{ marginBottom: 16 }}>{detail.address}</div>
                </div>
                <button
                  style={{
                    background: '#1976d2',
                    color: '#fff',
                    border: 'none',
                    borderRadius: 4,
                    padding: '7px 18px',
                    fontWeight: 600,
                    fontSize: 14,
                    cursor: 'pointer',
                    marginLeft: 'auto',
                    marginTop: 8,
                    height: 36,
                  }}
                  onClick={() => setModalOpen(true)}
                >
                  Contact Customer
                </button>
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: 12, margin: '16px 0 24px' }}>
                <div style={{ background: t.surface, border: `1px solid ${t.border}`, borderRadius: 6, padding: 12 }}>
                  <div style={{ fontSize: 12, color: t.textSecondary }}>Total Revenue</div>
                  <div style={{ fontSize: 18, fontWeight: 700, color: t.positive }}>
                    ${Number(detail.totalRevenue || 0).toLocaleString()}
                  </div>
                </div>
                <div style={{ background: t.surface, border: `1px solid ${t.border}`, borderRadius: 6, padding: 12 }}>
                  <div style={{ fontSize: 12, color: t.textSecondary }}>Open AR</div>
                  <div style={{ fontSize: 18, fontWeight: 700, color: t.warning }}>
                    ${Number(detail.openAR || 0).toLocaleString()}
                  </div>
                </div>
                <div style={{ background: t.surface, border: `1px solid ${t.border}`, borderRadius: 6, padding: 12 }}>
                  <div style={{ fontSize: 12, color: t.textSecondary }}>Invoice Count</div>
                  <div style={{ fontSize: 18, fontWeight: 700 }}>{Number(detail.invoiceCount || 0)}</div>
                </div>
              </div>
              <div style={{ display: 'flex', gap: 32, marginBottom: 24 }}>
                <div style={{ flex: 1 }}>
                  <h3 style={{ fontSize: 15, fontWeight: 600, marginBottom: 6 }}>Audit Statistics</h3>
                  <StatTable stats={detail.auditStats} t={t} />
                  <div style={{ height: 180, marginTop: 8, background: t.bgAlt, borderRadius: 8, padding: 8 }}>
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={Object.entries(detail.auditStats).map(([k, v]) => ({ name: k.charAt(0).toUpperCase() + k.slice(1), value: v }))}>
                        <XAxis dataKey="name" stroke={t.textSecondary} />
                        <YAxis stroke={t.textSecondary} />
                        <Tooltip />
                        <Bar dataKey="value" fill={t.accent} radius={[4, 4, 0, 0]} />
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </div>
                <div style={{ flex: 1 }}>
                  <h3 style={{ fontSize: 15, fontWeight: 600, marginBottom: 6 }}>Payment Statistics</h3>
                  <StatTable stats={detail.paymentStats} t={t} />
                  <div style={{ height: 180, marginTop: 8, background: t.bgAlt, borderRadius: 8, padding: 8 }}>
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={Object.entries(detail.paymentStats).map(([k, v]) => ({ name: k.charAt(0).toUpperCase() + k.slice(1), value: v }))}>
                        <XAxis dataKey="name" stroke={t.textSecondary} />
                        <YAxis stroke={t.textSecondary} />
                        <Tooltip />
                        <Bar dataKey="value" fill={t.positive} radius={[4, 4, 0, 0]} />
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </div>
              </div>
              <div style={{ marginBottom: 24 }}>
                <h3 style={{ fontSize: 15, fontWeight: 600, marginBottom: 6 }}>Detailed Analysis</h3>
                <AnalysisTable analysis={detail.analysis} t={t} />
                {/* Billing Bar Chart */}
                <div style={{ height: 220, marginTop: 16, background: t.bgAlt, borderRadius: 8, padding: 12 }}>
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={[
                      { name: 'Billed', value: detail.analysis.totalBilled },
                      { name: 'Paid', value: detail.analysis.totalPaid },
                      { name: 'Outstanding', value: detail.analysis.totalOutstanding },
                      { name: 'Overdue', value: detail.analysis.totalOverdue },
                    ]}>
                      <XAxis dataKey="name" stroke={t.textSecondary} />
                      <YAxis stroke={t.textSecondary} />
                      <Tooltip />
                      <Bar dataKey="value" fill={t.accent} radius={[4, 4, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
              <div>
                <h3 style={{ fontSize: 15, fontWeight: 600, marginBottom: 6 }}>Aging Report</h3>
                {aging ? (
                  <>
                    <AgingTable aging={aging} t={t} />
                    {/* Aging Pie Chart */}
                    <div style={{ height: 220, marginTop: 16, background: t.bgAlt, borderRadius: 8, padding: 12 }}>
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie
                            data={Object.entries(aging).map(([bucket, value]) => ({ name: bucket, value }))}
                            dataKey="value"
                            nameKey="name"
                            cx="50%"
                            cy="50%"
                            outerRadius={70}
                            label
                          >
                            {Object.entries(aging).map((entry, idx) => (
                              <Cell key={entry[0]} fill={[t.accent, t.positive, t.warning, t.error][idx % 4]} />
                            ))}
                          </Pie>
                          <Legend />
                          <Tooltip />
                        </PieChart>
                      </ResponsiveContainer>
                    </div>
                  </>
                ) : <span>Loading aging report...</span>}
              </div>
              <ContactCustomerModal
                open={modalOpen}
                onClose={() => setModalOpen(false)}
                onSend={handleSendMessage}
                customer={detail}
                invoice={null}
                exception={null}
              />
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function StatTable({ stats, t }) {
  return (
    <table style={{ fontSize: 13, background: t.surface, border: `1px solid ${t.border}`, borderRadius: 4, marginBottom: 8 }}>
      <tbody>
        {Object.entries(stats).map(([k, v]) => (
          <tr key={k}>
            <td style={{ padding: '4px 10px', color: t.textSecondary }}>{k.charAt(0).toUpperCase() + k.slice(1)}</td>
            <td style={{ padding: '4px 10px', fontWeight: 600 }}>{v}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function AnalysisTable({ analysis, t }) {
  return (
    <table style={{ fontSize: 13, background: t.surface, border: `1px solid ${t.border}`, borderRadius: 4, marginBottom: 8 }}>
      <tbody>
        {Object.entries(analysis).map(([k, v]) => (
          <tr key={k}>
            <td style={{ padding: '4px 10px', color: t.textSecondary }}>{k.replace(/([A-Z])/g, ' $1').replace(/^./, s => s.toUpperCase())}</td>
            <td style={{ padding: '4px 10px', fontWeight: 600 }}>{typeof v === 'number' ? v.toLocaleString() : v}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function AgingTable({ aging, t }) {
  return (
    <table style={{ fontSize: 13, background: t.surface, border: `1px solid ${t.border}`, borderRadius: 4, marginBottom: 8 }}>
      <thead>
        <tr>
          <th style={{ padding: '4px 10px', color: t.textSecondary }}>Aging Bucket</th>
          <th style={{ padding: '4px 10px', color: t.textSecondary }}>Amount</th>
        </tr>
      </thead>
      <tbody>
        {Object.entries(aging).map(([bucket, amount]) => (
          <tr key={bucket}>
            <td style={{ padding: '4px 10px' }}>{bucket}</td>
            <td style={{ padding: '4px 10px', fontWeight: 600 }}>{amount.toLocaleString()}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

